SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE instruction_id = #{instructionId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_color_instruction_color
WHERE instruction_id = #{instructionId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
